INSERT INTO `post1` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (407636,'بي بي سي عربي','2026-10-25 15:10:35','<p>توافد آلاف الأردنيين إلى قرية حمود بمحافظة الكرك لتشييع جثامين ثمانية من ضحايا الهجوم المسلح الذي استهدف كنيسة يوم الجمعة، ومن المقرر تشييع جثمان القتيل التاسع الاثنين في العاصمة عمّان.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/c3gr8dqwgwr1o?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','آلاف الأردنيين يودّعون ضحايا هجوم كنيسة الكرك بالترانيم والورود','2026-10-25 19:35:52','',1,0,0,0,0,0,0,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/6ea8/live/f2014a20-d083-11f1-a701-fddedf244c16.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/c3gr8dqwgwr1o?at_medium=RSS&at_campaign=rss',0),(407635,'بي بي سي عربي','2026-10-25 18:47:06','<p>ينتظر قرار إرسال قوات جزائرية إلى النيجر تصويت الغرفة السفلى، تمهيداً لأول انتشار عسكري خارج الحدود الجزائرية منذ حرب 1973.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/ckwyq1l4enp9o?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مجلس الأمة الجزائري يوافق بالإجماع على إرسال قوات إلى النيجر','2026-10-25 19:35:52','',1,0,0,0,0,0,1,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/8e7d/live/ecf6efb0-d085-11f1-a4ba-351760cfea6a.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/ckwyq1l4enp9o?at_medium=RSS&at_campaign=rss',0),(407642,'بي بي سي عربي','2026-10-25 15:02:24','<p>العملية العسكرية الإسرائيلية واسعة النطاق تتواصل في الضفة الغربية . فلسطينيون يقولون إنها عقاب جماعي والمسؤولون الإسرائيليون يقولون إنها تأمين للمواطنين الإسرائيليين وعقاب للإرهابيين.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/cq8rzm3leznvo?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الضفة الغربية: كيف يؤثر التصعيد الجاري في حياة الفلسطينيين؟','2026-10-25 19:35:52','',1,0,0,0,0,0,0,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/6154/live/154d6450-d084-11f1-a4ba-351760cfea6a.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/cq8rzm3leznvo?at_medium=RSS&at_campaign=rss',0),(407638,'بي بي سي عربي','2026-10-25 13:27:25','<p>سبعة قتلى في غارات إسرائيلية على قطاع غزة، بينهم ثلاثة موظفين في الجامعة الإسلامية، وإصابة عشرة آخرين على الأقل في غارتين استهدفتا الجامعة، بحسب مصادر طبية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/cqx29p7jnpylo?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هجمات إسرائيلية تقتل ثمانية في غزة رغم وقف إطلاق النار','2026-10-25 19:35:52','',1,0,0,0,0,0,0,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/8559/live/3a4d08a0-d089-11f1-b441-2b33b063138f.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/cqx29p7jnpylo?at_medium=RSS&at_campaign=rss',0),(407634,'بي بي سي عربي','2026-10-25 18:28:08','<p>أعلنت جماعة أنصار الله الحوثية، الأحد، استهداف مطار الرياض وقاعدتين عسكريتين جنوبي السعودية بـ&quot;عشرات الصواريخ الباليستية&quot;. في المقابل، أعلن التحالف بقيادة السعودية اعتراض عشرة صواريخ أُطلقت باتجاه جنوب المملكة، فيما اتهم الحوثيون الرياض بشن 56 غارة جوية وهجوم صاروخي على اليمن خلال 24 ساعة. ويتزامن التصعيد مع إعلان نقل رالي دكار 2027 خارج السعودية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/crq8n4zx8l4zo?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','\"أنصار الله\" تعلن استهداف مطار الرياض والسعودية تؤكد اعتراض صواريخ بالستية','2026-10-25 19:35:52','',1,0,0,0,0,0,1,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/34cd/live/ffb81e70-d09f-11f1-87fa-c1809f43a7a8.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/crq8n4zx8l4zo?at_medium=RSS&at_campaign=rss',0),(407637,'بي بي سي عربي','2026-10-25 16:57:34','<p>إجراء الانتخابات الإسرائيلية وسط حالة من الحذر وإجراءات أمنية مشددة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/cw3djmn2exylo?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','إسرائيل تعلن إغلاق معابر الضفة الغربية خلال الانتخابات','2026-10-25 19:35:52','',1,0,1,0,0,0,0,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/7ed5/live/931125e0-d07d-11f1-a4ba-351760cfea6a.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/cw3djmn2exylo?at_medium=RSS&at_campaign=rss',0),(407639,'بي بي سي عربي','2026-10-25 14:35:06','<p>تجمع آلاف الأردنيين في قرية حمود في الكرك، جنوبي الأردن، لتشييع جثامين الضحايا الذين وقعوا إثر الهجوم المسلح الذي وقع يوم الجمعة في كنيسة الروم الأرثوذوكس في الكرك.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/cwp9gj7p8dx4o?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','كيف ودع الأردنيون ضحايا هجوم الكنيسة؟','2026-10-25 19:35:52','',1,0,0,0,0,0,0,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/e8f1/live/236b7700-d081-11f1-a701-fddedf244c16.jpg',NULL,'fa fa-star-half-alt','بي بي سي عربي','https://www.bbc.com/arabic/articles/cwp9gj7p8dx4o?at_medium=RSS&at_campaign=rss',0),(407631,'فرانس 24','2026-10-25 15:18:51','<p>صادق مجلس الأمة الجزائري (الغرفة العليا في البرلمان)، الأحد، على مقترح يسمح بإرسال قوات مسلحة إلى دولة النيجر المجاورة، وفق ما أفاد عضو في المجلس لوكالة الأنباء الفرنسية. وسيتم عرض المقترح على نواب المجلس الشعبي الوطني (الغرفة السفلى) في وقت لاحق من اليوم، ليصبح نهائيا. وسيكون هذا الانتشار العسكري خارج الحدود في حال حصوله، الأول من نوعه، منذ أن أرسلت الجزائر قوات لدعم مصر خلال الحرب العربية الإسرائيلية في العام 1973.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D8%A3%D9%81%D8%B1%D9%8A%D9%82%D9%8A%D8%A7/20261025-%D8%A7%D9%84%D9%85%D8%AC%D9%84%D8%B3-%D8%A7%D9%84%D8%B4%D8%B9%D8%A8%D9%8A-%D9%85%D8%AC%D9%84%D8%B3-%D8%A7%D9%84%D8%A3%D9%85%D8%A9-%D8%A7%D9%84%D8%AC%D8%B2%D8%A7%D8%A6%D8%B1-%D8%A5%D8%B1%D8%B3%D8%A7%D9%84-%D9%82%D9%88%D8%A7%D8%AA-%D9%85%D8%B3%D9%84%D8%AD%D8%A9-%D8%A7%D9%84%D9%86%D9%8A%D8%AC%D8%B1\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','في انتظار تصويت المجلس الشعبي... مجلس الأمة بالجزائر يوافق على إرسال قوات مسلحة للنيجر','2026-10-25 19:35:50','أفريقيا',1,0,0,0,0,0,0,'https://s.france24.com/media/display/b1b9a8f0-a52b-11f1-bc2e-005056a97e36/w:1024/p:16x9/niger-2.jfif',NULL,'fa fa-star-half-alt','فرانس 24','https://www.france24.com/ar/%D8%A3%D9%81%D8%B1%D9%8A%D9%82%D9%8A%D8%A7/20261025-%D8%A7%D9%84%D9%85%D8%AC%D9%84%D8%B3-%D8%A7%D9%84%D8%B4%D8%B9%D8%A8%D9%8A-%D9%85%D8%AC%D9%84%D8%B3-%D8%A7%D9%84%D8%A3%D9%85%D8%A9-%D8%A7%D9%84%D8%AC%D8%B2%D8%A7%D8%A6%D8%B1-%D8%A5%D8%B1%D8%B3%D8%A7%D9%84-%D9%82%D9%88%D8%A7%D8%AA-%D9%85%D8%B3%D9%84%D8%AD%D8%A9-%D8%A7%D9%84%D9%86%D9%8A%D8%AC%D8%B1',0),(407632,'فرانس 24','2026-10-25 13:00:31','<p>أعلنت إسرائيل الأحد أنها ستغلق كل المعابر البرية مع الضفة الغربية يوم الانتخابات الأسبوع المقبل، متوعدة في الوقت نفسه بتدفيع الثمن باهظا ردا على مقتل جنديين في هجوم نفذه مسلّحان فلسطينيان.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D9%81%D9%8A%D8%AF%D9%8A%D9%88/20261025-%D8%A7%D9%84%D8%A7%D9%86%D8%AA%D8%AE%D8%A7%D8%A8%D8%A7%D8%AA-%D8%A7%D9%84%D8%A5%D8%B3%D8%B1%D8%A7%D8%A6%D9%8A%D9%84%D9%8A%D8%A9-%D8%A5%D8%AC%D8%B1%D8%A7%D8%A1%D8%A7%D8%AA-%D8%A3%D9%85%D9%86%D9%8A%D8%A9-%D9%85%D8%B4%D8%AF%D8%AF%D8%A9-%D9%81%D9