INSERT INTO `post2` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (407443,'اندبندنت عربية','2026-10-09 21:00:00','<p>تتسع الفجوة في صافي الثروة بين الأجيال مع التقدم في العمر، إذ تتراكم الأصول والمدخرات والاستثمارات على مدى العقود، قبل أن تبدأ الثروة في التراجع عادة بعد سن الـ75 مع السحب من مدخرات التقاعد. وتكشف البيانات أن جيل طفرة المواليد وأكبر أبناء الجيل &quot;إكس&quot; يمتلكون أعلى قيمة وسطية لصافي الثروة، فيما يبقى الادخار وتسديد الديون والاستثمار المنتظم أبرز وسائل بناء الثروة على المدى الطويل.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659901\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','كيف يتغير صافي ثروة المرء مع التقدم في العمر؟','2026-10-25 19:35:43','أخبار وتقارير اقتصادية',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/07/1175905-16472852.jpg',NULL,'fa-solid fa-money-bill-wave','اندبندنت عربية','https://www.independentarabia.com/node/659901',0),(407442,'اندبندنت عربية','2026-10-11 12:28:55','<p>تواجه بريطانيا شتاءً محفوفاً بأخطار انقطاع الكهرباء، في ظل تراجع احتياطات الغاز، وتزايد الطلب من مراكز البيانات، وتأخر تحديث الشبكة، وهدر طاقة الرياح. وبين التهديدات السيبرانية واختناقات نقل الكهرباء، تتزايد المخاوف من اضطرار السلطات إلى تقنين الإمدادات، في اختبار صعب لأمن الطاقة البريطاني.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660167\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بريطانيا في الظلام: نفاد الغاز ليس التهديد الوحيد هذا الشتاء','2026-10-25 19:35:43','أخبار وتقارير اقتصادية',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/11/1176374-865690226.jpg',NULL,'fa-solid fa-money-bill-wave','اندبندنت عربية','https://www.independentarabia.com/node/660167',0),(407441,'اندبندنت عربية','2026-10-13 21:00:00','<p>يكشف استطلاع جديد اتساع الفجوة بين السن التي يطمح البريطانيون إلى التقاعد عندها والسن التي يتوقعون أن يتمكنوا فيها فعلياً من التوقف عن العمل، لتتجاوز خمسة أعوام للمرة الأولى. ويعزو كثر ذلك إلى الضغوط المعيشية وضعف المدخرات، فيما يخشى ثلثا العاملين عدم ادخار ما يكفي لأعوام التقاعد.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660184\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','البريطانيون يؤجلون التقاعد قسرا مع تنامي المخاوف على مدخراتهم','2026-10-25 19:35:43','أخبار وتقارير اقتصادية',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/11/1176396-99671840.jpg',NULL,'fa-solid fa-money-bill-wave','اندبندنت عربية','https://www.independentarabia.com/node/660184',0);
