INSERT INTO `post5` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405602,'فرانس 24','2026-10-25 17:03:32','<p>أعلن الاتحاد الدولي للسيارات (فيا)، الأحد، أن السعودية لن تستضيف النسخة المقبلة من رالي داكار المقررة بين 1 و15 يناير/كانون الثاني 2027، على خلفية التطورات الأمنية في المنطقة، في قرار يأتي وسط اضطرابات إقليمية أدت أيضا إلى إلغاء أو تأجيل مناسبات رياضية كبرى عدة. وأكد البيان أن الرالي سيُقام على أراضٍ أخرى، على أن تستضيف السعودية نسخة 2028 التاريخية التي تمثل النسخة الخمسين من الرالي الصحراوي الشهير.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/20261025-%D8%AA%D8%A3%D8%AC%D9%8A%D9%84-%D8%B1%D8%A7%D9%84%D9%8A-%D8%AF%D8%A7%D9%83%D8%A7%D8%B1-2027-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%B9%D8%A7%D9%85-%D8%B3%D8%A8%D8%A8-%D8%A7%D9%84%D8%AA%D8%B7%D9%88%D8%B1%D8%A7%D8%AA-%D8%A7%D9%84%D8%A3%D9%85%D9%86%D9%8A%D8%A9-%D9%87%D8%AC%D9%85%D8%A7%D8%AA-%D8%A7%D9%84%D8%AD%D9%88%D8%AB%D9%8A%D9%8A%D9%86\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','رالي داكار 2027 يُنقل خارج السعودية... والمملكة تحتضن النسخة الخمسين في 2028','2026-10-25 19:35:50','رياضة',1,0,0,1,0,0,0,'https://s.france24.com/media/display/bc72b5e2-cdd8-11ef-88a9-005056a90284/w:1024/p:16x9/000_36TA4WR.jpg',NULL,'fa-solid fa-futbol','فرانس 24','https://www.france24.com/ar/%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/20261025-%D8%AA%D8%A3%D8%AC%D9%8A%D9%84-%D8%B1%D8%A7%D9%84%D9%8A-%D8%AF%D8%A7%D9%83%D8%A7%D8%B1-2027-%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9-%D8%B9%D8%A7%D9%85-%D8%B3%D8%A8%D8%A8-%D8%A7%D9%84%D8%AA%D8%B7%D9%88%D8%B1%D8%A7%D8%AA-%D8%A7%D9%84%D8%A3%D9%85%D9%86%D9%8A%D8%A9-%D9%87%D8%AC%D9%85%D8%A7%D8%AA-%D8%A7%D9%84%D8%AD%D9%88%D8%AB%D9%8A%D9%8A%D9%86',0),(405611,'فرانس 24','2026-10-25 10:23:47','<p>تمكنت أندية بيراميدز والزمالك المصريان والترجي التونسي ونهضة بركان المغربي من بلوغ دور المجموعات لمسابقة دوري أبطال أفريقيا في كرة القدم بانتصاراتها، السبت، في إياب الدور التمهيدي الثاني، فيما أُقصي المريخ السوداني بركلات الترجيح.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/20261025-%D8%AF%D9%88%D8%B1%D9%8A-%D8%A3%D8%A8%D8%B7%D8%A7%D9%84-%D8%A3%D9%81%D8%B1%D9%8A%D9%82%D9%8A%D8%A7-%D8%A8%D9%8A%D8%B1%D8%A7%D9%85%D9%8A%D8%AF%D8%B2-%D8%A7%D9%84%D8%B2%D9%85%D8%A7%D9%84%D9%83-%D8%A7%D9%84%D8%AA%D8%B1%D8%AC%D9%8A-%D9%86%D9%87%D8%B6%D8%A9-%D8%A8%D8%B1%D9%83%D8%A7%D9%86-%D8%AF%D9%88%D8%B1-%D8%A7%D9%84%D9%85%D8%AC%D9%85%D9%88%D8%B9%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B1%D9%8A%D8%AE\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','دوري أبطال أفريقيا: بيراميدز والزمالك والترجي ونهضة بركان إلى دور المجموعات والمريخ يودع المسابقة','2026-10-25 19:35:50','رياضة',1,0,0,1,0,0,0,'https://s.france24.com/media/display/bef5fc94-36fe-11f1-b0e5-005056a97e36/w:1024/p:16x9/000-A7K69PR.jpg',NULL,'fa fa-rocket','فرانس 24','https://www.france24.com/ar/%D8%B1%D9%8A%D8%A7%D8%B6%D8%A9/20261025-%D8%AF%D9%88%D8%B1%D9%8A-%D8%A3%D8%A8%D8%B7%D8%A7%D9%84-%D8%A3%D9%81%D8%B1%D9%8A%D9%82%D9%8A%D8%A7-%D8%A8%D9%8A%D8%B1%D8%A7%D9%85%D9%8A%D8%AF%D8%B2-%D8%A7%D9%84%D8%B2%D9%85%D8%A7%D9%84%D9%83-%D8%A7%D9%84%D8%AA%D8%B1%D8%AC%D9%8A-%D9%86%D9%87%D8%B6%D8%A9-%D8%A8%D8%B1%D9%83%D8%A7%D9%86-%D8%AF%D9%88%D8%B1-%D8%A7%D9%84%D9%85%D8%AC%D9%85%D9%88%D8%B9%D8%A7%D8%AA-%D8%A7%D9%84%D9%85%D8%B1%D9%8A%D8%AE',0),(405592,'اندبندنت عربية','2026-10-11 16:39:25','<p>يعيش مانشستر يونايتد بداية متعثرة تعيد إلى الأذهان أسوأ مواسمه التاريخية، وسط تراجع الأداء البدني والتكتيكي، وتعدد الأخطاء الدفاعية، وتصاعد التساؤلات حول قدرة مايكل كاريك على إعادة الفريق إلى المسار الصحيح.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660192\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بداية مانشستر يونايتد المتعثرة تكشف عن أزمة متجذرة','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/11/1176406-1634963333.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660192',0),(405591,'اندبندنت عربية','2026-10-12 13:03:18','<p>حقق مانشستر سيتي فوزاً بثلاثية نظيفة على ليفربول في مباراة استثنائية، امتزج فيها التألق الكروي بأزمة الاتهامات والعقوبات، وسط احتجاجات جماهيرية كشفت عمق الانقسام حول مستقبل الدوري الإنجليزي الممتاز.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660254\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مانشستر سيتي يسحق ليفربول في أنفيلد... فهل كان الفوز بلا قيمة؟','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/12/1176537-1490933680.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660254',0),(405590,'اندبندنت عربية','2026-10-12 13:17:32','<p>أنهى مانشستر سيتي سلسلة أندوني إيراولا الخالية من الهزائم، كاشفاً ثغرات ليفربول في عمق التشكيلة وفاعلية الصفقات الكبرى، ومثيراً تساؤلات حول مستقبل مشروع المدرب الإسباني وطموحاته.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660258\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ليفربول أمام سؤال صعب بعد كشف مانشستر سيتي ثغرة كبيرة','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/12/1176539-421499609.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660258',0),(405589,'اندبندنت عربية','2026-10-13 14:26:53','<p>قد يؤدي غياب مانشستر سيتي المحتمل عن دوري أبطال أوروبا إلى الكشف عن حدود القوة المالية للأندية الإنجليزية، وإعادة رسم خريطة المنافسة القارية، في ظل تراجع كبار &quot;البريميرليغ&quot; وصعود المنافسين الأوروبيين.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660356\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لا مجال للهيمنة... مستقبل قاتم للأندية الإنجليزية في دوري الأبطال','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/13/1176722-639555025.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660356',0),(405588,'اندبندنت عربية','2026-10-14 12:12:10','<p>يواجه مانشستر سيتي خطر الغياب عن دوري أبطال أوروبا بعد أحكام في اتهامات مالية تهدد مستقبله، بينما يحاول إنزو ماريسكا ولاعبوه تجاهل الضغوط والتركيز على المنافسة داخل الملعب.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660429\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا تبدو رحلة مانشستر سيتي الأوروبية مختلفة هذا الموسم؟','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/14/1176831-1393523850.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660429',0),(405587,'اندبندنت عربية','2026-10-15 11:59:35','<p>يتصدر باريس سان جيرمان وبرشلونة مشهد دوري أبطال أوروبا بعد انتصارات لافتة، فيما تشتعل المنافسة بين كبار القارة على المراكز المتقدمة، وسط تباين النتائج وتزايد التوقعات حول هوية البطل المرتقب.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660496\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','باريس وبرشلونة في اختبار صدارة الكبار','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/15/1176947-106730467.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660496',0),(405586,'اندبندنت عربية','2026-10-16 13:04:57','<p>يبرز إنزو ماريسكا كخليفة جدير لبيب غوارديولا في مانشستر سيتي، بفضل قدرته على تغيير مسار المباريات وقراءة المنافسين، على رغم التحديات الإدارية والقانونية التي تهدد مستقبل النادي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660580\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','كيف بدأ إنزو ماريسكا في الخروج من عباءة غوارديولا؟','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/16/1177098-1525213984.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660580',0),(405585,'اندبندنت عربية','2026-10-19 10:57:29','<p>حقق أرسنال 10 انتصارات في 11 مباراة، لكن فوزه الشاق على نوتنغهام فورست كشف عن مشكلات هجومية وتكتيكية تثير التساؤلات حول قدرة ميكيل أرتيتا على قيادة الفريق للاحتفاظ بلقب الدوري الإنجليزي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660768\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','فوز أرسنال الباهت إلى حد الملل يكشف عن منحى مقلق','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/19/1177404-1124448617.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660768',0),(405584,'اندبندنت عربية','2026-10-19 12:45:10','<p>يسعى مايكل كاريك لإنقاذ موسم مانشستر يونايتد عبر إعادة بناء خط الوسط وتعزيز الصلابة الدفاعية، لكن التعادلات المتتالية والأرقام الهجومية الضعيفة تثير الشكوك حول قدرته على إحداث تحول حقيقي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660784\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا يثق كاريك أن مانشستر يونايتد بدأ أخيرا مرحلة طال انتظارها؟','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/19/1177440-1478147028.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660784',0),(405583,'اندبندنت عربية','2026-10-21 11:12:27','<p>تتجه الأنظار إلى مواجهة بايرن ميونيخ وأرسنال في دوري أبطال أوروبا، إذ يتصادم الهجوم الكاسح مع الدفاع الصلب، في اختبار حاسم لفلسفتين مختلفتين وطموحين نحو اللقب القاري.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660929\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بايرن ميونيخ يترقب ثغرة في خطة أرسنال بدوري أبطال أوروبا','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/21/1177666-2066188874.jpeg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660929',0),(405582,'اندبندنت عربية','2026-10-22 09:40:06','<p>تتصاعد الأزمة داخل مانشستر يونايتد مع انفجار الخلاف بين برونو فيرنانديز ومايكل كاريك، وسط تراجع النتائج وانهيار الانسجام، ومؤشرات تنذر بنهاية مبكرة لتجربة المدرب.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660982\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','خلاف برونو فيرنانديز وكاريك يكشف عن أزمة مانشستر يونايتد','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/22/1177787-145388993.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660982',0),(405581,'اندبندنت عربية','2026-10-22 09:49:24','<p>خطف ريو نغوموها الأضواء مع ليفربول في دوري أبطال أوروبا، مؤكداً موهبته الاستثنائية وسرعته وقوته على رغم صغر سنه، وسط إشادة بذكائه التكتيكي وتطوره التدرجي وطموحه لصناعة مستقبل كبير.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660986\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الليلة التي تحول فيها ريو نغوموها إلى خطر داهم','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/22/1177789-1937594977.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/660986',0),(405580,'اندبندنت عربية','2026-10-23 11:17:34','<p>اندلعت حرب تصريحات بين ريال مدريد وبرشلونة ورابطة الدوري الإسباني قبل الكلاسيكو المرتقب، وسط جدل نيغريرا واتهامات التحكيم، وعودة جوزيه مورينيو لمواجهة مشتعلة تجمع النجوم بالضغوط التاريخية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661077\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','تصاعد التوتر بين برشلونة وريال مدريد ينذر بـ\"كلاسيكو\" ناري','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/23/1177930-795952340.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/661077',0),(405579,'اندبندنت عربية','2026-10-23 13:47:23','<p>يقترب هاري كين من تحقيق حلم الكرة الذهبية، مدعوماً بأرقامه الاستثنائية وتأثيره الحاسم مع بايرن ميونيخ، وسط منافسة لامين يامال وترقب لحظة قد تنهي انتظاراً إنجليزياً دام ربع قرن.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661095\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هاري كين يقلب موازين الجدل حول الكرة الذهبية','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/23/1177964-575426700.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/661095',0),(405578,'اندبندنت عربية','2026-10-24 00:05:31','<p>تتصاعد الضغوط على مايكل كاريك بعد تراجع نتائج مانشستر يونايتد، وسط تحركات لاختيار بديل محتمل يعيد الفريق إلى المنافسة، من إيدي هاو وأوناي إيمري إلى كونتي وناغلسمان.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661120\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','من هو مدرب مانشستر يونايتد القادم خلفا لمايكل كاريك؟','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/24/1177999-952219070.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/661120',0),(405577,'اندبندنت عربية','2026-10-24 10:41:15','<p>يعيد جوردان هندرسون الانضباط والحيوية لتشيلسي بفضل خبرته ولياقته الاستثنائية، فيما يراهن تشابي ألونسو على نضج لاعبيه للسيطرة على الانفعالات أمام توتنهام، بالتزامن مع استعداد الحارس الشاب مايك بيندرز لتعويض إصابة مارتينيز.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661141\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا يوائم هندرسون تشيلسي الجديد بقيادة تشابي ألونسو؟','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/24/1178040-1777629293.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/661141',0),(405576,'اندبندنت عربية','2026-10-24 13:15:09','<p>أقر مايكل كاريك بأن مانشستر يونايتد فقد هويته موقتاً، متعهداً باستعادة أمجاد الفريق عبر التواضع والتضحية والعمل الجاد، وسط ضغوط متصاعدة عقب سلسلة نتائج سلبية وانتقادات برونو فيرنانديز.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661163\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مايكل كاريك يواجه ضغوط مانشستر يونايتد برسالة حماسية','2026-10-25 19:35:43','رياضة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/24/1178076-2025700623.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/661163',0),(405575,'اندبندنت عربية','2026-10-25 13:46:33','<p>نجح أستون فيلا بقيادة أوناي إيمري في إسقاط مانشستر سيتي، مستفيداً من الضغط المتواصل والفاعلية الهجومية والأخطاء الدفاعية، ليؤكد تطوره المتسارع ويكشف عن ثغرات بطل الدوري الإنجليزي الممتاز.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661250\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','أستون فيلا المجدد يكشف عن ثغرات مانشستر سيتي بعد الكمال','2026-10-25 19:35:43','رياضة',1,0,0,1,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/25/1178213-792504395.jpg',NULL,'fa-solid fa-futbol','اندبندنت عربية','https://www.independentarabia.com/node/661250',0);
