INSERT INTO `post6` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405535,'اندبندنت عربية','2026-10-01 13:57:59','<p>يسرد كتاب بن ماكنتير الجديد &quot;ريدوود&quot; قصة جاسوس سوفياتي قادته أزمة زواجه إلى أحضان الاستخبارات البريطانية، لتصبح هشاشته الشخصية مدخلاً إلى واحدة من أخطر عمليات التجسس في الحرب الباردة، في حكاية تكشف أن التاريخ لا تصنعه الاستراتيجيات الكبرى وحدها، بل أيضاً الحب والخوف والغرور والضعف.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659367\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الجاسوس الذي خان بلاده في محاولة لإنقاذ زواجه','2026-10-25 19:35:43','كتب',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/01/1174946-1136021989.jpg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/659367',0),(405534,'اندبندنت عربية','2026-10-02 10:52:01','<p>تكشف مذكرات سيلفستر ستالون الجديدة &quot;الخطوات&quot; الوجه الآخر لرحلته نحو النجومية، مستعيدة أعوام الفقر والرفض والأعمال الشاقة والعلاقات العائلية المضطربة، وصولاً إلى الرهان الذي غير حياته: كتابة &quot;روكي&quot; والتمسك ببطولته، قبل أن يتحول الفيلم إلى نجاح مدو ويتوج بجائزة &quot;أوسكار&quot;.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659420\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مذكرات سيلفستر ستالون: الطريق الوعر إلى \"روكي\"','2026-10-25 19:35:43','سينما',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/02/1175036-1415625038.jpg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/659420',0),(405533,'اندبندنت عربية','2026-10-03 12:41:00','<p>تواجه نجمات هوليوود أحكاماً متناقضة مع التقدم في العمر، فالتدخلات التجميلية تعرضهن للانتقاد، فيما يتحول الظهور بملامح طبيعية ومن دون مكياج إلى فعل استثنائي يستدعي المديح. وتجربة باميلا أندرسون تكشف ازدواجية معايير الجمال التي تلاحق النساء تحت الأضواء، في مقابل قدر أقل بكثير من التدقيق في مظهر الرجال مع تقدمهم في السن.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659516\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','المرأة الستينية في هوليوود... مدانة مهما فعلت','2026-10-25 19:35:43','فنون',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/03/1175290-1651819750.jpg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/659516',0),(405532,'اندبندنت عربية','2026-10-08 13:00:19','<p>ستة ممثلين جسدوا شخصية جيمس بوند على مدى عقود، وترك كل منهم بصمته الخاصة على العميل 007، من أناقة شون كونري وسخرية روجر مور إلى قتامة تيموثي دالتون وقسوة دانييل كريغ. ورغم نجاح كريغ في إعادة ابتكار الشخصية ومنحها عمقاً إنسانياً، يتصدر كونري القائمة بوصفه صاحب الأداء الذي رسم الملامح الأصلية لأشهر جاسوس في تاريخ السينما.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659953\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','جيمس بوند: من كان الأفضل في تجسيد العميل 007؟','2026-10-25 19:35:43','سينما',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/08/1176022-1195913792.jpeg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/659953',0),(405531,'اندبندنت عربية','2026-10-08 13:00:59','<p>من أسرار مطاعم لندن وحياة مشاهيرها الصاخبة، إلى سيرة روائي إيرلندي مثقل بطفولة قاسية، ورواية تستكشف إرث الإرهاب داخل العائلة، ننتقي لكم أبرز كتب أكتوبر في بريطانيا، في جولة تجمع التاريخ والأدب والطعام والأسرار العائلية والوجوه المعتمة للحياة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659954\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','أهم إصدارات بريطانيا خلال شهر أكتوبر 2026','2026-10-25 19:35:43','كتب',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/08/1175986-607053700.jpg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/659954',0),(405530,'اندبندنت عربية','2026-10-10 07:45:20','<p>تشهد بريطانيا تصاعداً مقلقاً في الضغوط الرامية إلى فرض الرقابة على الكتب، سواء في المدارس أو المكتبات العامة. وبينما تكفي أحياناً شكوى واحدة لسحب كتاب من الرفوف، يحذر المدافعون عن حرية التعبير من أن تقييد الوصول إلى الكتب، خصوصاً تلك التي تعكس تجارب ووجهات نظر متنوعة، يهدد الحق في القراءة الحرة ويقوض قيم الشمول والتفكير النقدي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660069\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','حرية القراءة في مهب الرقابة البريطانية','2026-10-25 19:35:43','ثقافة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/10/1176191-689469519.jpg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/660069',0),(405529,'اندبندنت عربية','2026-10-20 12:00:20','<p>يرى روبرت ماكرام أن الأدب لا يواجه اليوم رقابة الدولة وحدها، بل ضغوطاً جديدة تتمثل في ثقافة المشاهير والرقابة الذاتية وتسليع الإبداع وهيمنة الذكاء الاصطناعي. ومن خلال استحضار تجربتي جورج أورويل وويليام غولدينغ، يجادل بأن الفكر الأصيل لا يزال قادراً على الصمود، لكن الكتّاب باتوا مطالبين بيقظة أكبر للحفاظ على استقلالهم الإبداعي وسط ضوضاء العصر الرقمي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660849\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هل يختنق الأدب بين الرقابة المعاصرة والضغوط الرقمية؟','2026-10-25 19:35:43','ثقافة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/20/1177536-604836352.jpg',NULL,'fa fa-book','اندبندنت عربية','https://www.independentarabia.com/node/660849',0);
