INSERT INTO `post7` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (52,'اندبندنت عربية','2026-10-25 11:25:03','<p>تحذر الحكومة البريطانية من أن خصوم البلاد قد يمتلكون بحلول عام 2030 القدرة على شن هجوم، فيما يقول وزير الدفاع إن أمام بريطانيا ما يزيد قليلاً على ألف يوم لرفع جاهزيتها العسكرية مع حلفائها. وتدعو حملة &quot;كن مستعداً&quot; الأسر والشركات إلى تجهيز احتياجات أساسية تحسباً لتعطل الخدمات، بينما ترى الاستخبارات البريطانية أن مرحلة الاستقرار النسبي التي أعقبت الحرب الباردة انتهت وأن الأخطار الراهنة ستستمر.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661228\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','وزير الدفاع البريطاني: علينا الاستعداد للحرب خلال 1000 يوم','2026-10-25 19:35:43','تقارير',1,0,0,0,1,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/25/1178168-1582535164.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/661228',0),(53,'اندبندنت عربية','2026-10-24 13:00:15','<p>يواجه بنيامين نتنياهو احتمال خسارة الأغلبية البرلمانية في الانتخابات الإسرائيلية، وسط توقعات بتراجع مقاعد حزبه &quot;الليكود&quot; وحلفائه اليمينيين. لكن تعثر معسكره لا يضمن وصول المعارضة إلى السلطة، إذ قد تتوقف معادلة الحكم على الأحزاب العربية ونتائج &quot;الكتلة الثالثة&quot;، مع بقاء احتمال إجراء انتخابات جديدة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661161\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ائتلاف نتنياهو مهدد بفقدان الأغلبية في الانتخابات الإسرائيلية','2026-10-25 19:35:43','متابعات',1,0,0,0,1,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/24/1178071-1649809915.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/661161',0),(54,'اندبندنت عربية','2026-10-23 12:57:26','<p>يرى شون أوغرايدي أن موافقة حكومة العمال على تطوير حقل &quot;جاكدو&quot; للغاز ليست تراجعاً عن الأهداف البيئية، بل خطوة براغماتية تعزز أمن الطاقة وتحد من الاعتماد على الواردات، من دون أن تخفض الفواتير. ويخلص إلى أن الطاقة الخضراء تظل الرهان الوحيد القادر على تحقيق أمن الطاقة وخفض الكلفة والوصول إلى صافي الانبعاثات الصفري.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661091\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','رهان بيرنهام على غاز بحر الشمال: خطوة براغماتية لا انتكاسة بيئية','2026-10-25 19:35:43','تحلیل',1,0,0,0,1,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/23/1177952-597081287.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/661091',0),(55,'اندبندنت عربية','2026-10-23 12:04:32','<p>تحذر حكومة بريطانيا مواطنيها من احتمال تعرض البلاد لنقص في الغذاء وتعطل الخدمات الأساسية نتيجة هجمات سيبرانية وأعمال تخريبية ترعاها دول معادية. وفي ظل تصاعد التهديدات السيبرانية والتوتر مع روسيا، دعت المواطنين إلى الاحتفاظ بمخزونات طوارئ من المياه والغذاء والنقود والأدوية لتعزيز قدرة البلاد على الصمود في الأزمات.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661085\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','وزير الدفاع البريطاني لمواطنيه: خزنوا الغذاء تحسبا لهجمات تخريبية','2026-10-25 19:35:43','متابعات',1,0,0,0,1,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/23/1177942-1671585858.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/661085',0),(56,'اندبندنت عربية','2026-10-21 21:00:00','<p>تحولت &quot;بوتس&quot; من رمز بريطاني للابتكار في الصيدلة والتجزئة إلى علامة تجارية باهتة أنهكتها تغيرات الملكية وضعف الاستثمار، في مسار يعكس تراجعاً أوسع في ثقة بريطانيا بقدرتها على الابتكار والإنتاج. وتتقاطع قصة الشركة مع أزمات التقشف و&quot;بريكست&quot; و&quot;كورونا&quot; وتدهور الخدمات الصحية، فيما يفتح استحواذ عائلة &quot;ويستون&quot; باباً أمام احتمال استعادة &quot;بوتس&quot; شيئاً من مجدها السابق.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660885\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا أصبحت بريطانيا \"رجل أوروبا المريض\"؟','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/20/1177601-1969472379.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660885',0),(57,'اندبندنت عربية','2026-10-19 15:15:43','<p>تحولت احتجاجات بدأت في المدارس الفرنسية بسبب نقص الموارد وتهالك المرافق إلى حراك واسع تغذيه أزمة غلاء المعيشة وتراجع الرعاية الاجتماعية، وسط مواجهات عنيفة مع الشرطة وإصابات خطرة. ومع استغلال القوى السياسية للأزمة وظهور اضطرابات مماثلة في بلجيكا وإيطاليا، تتزايد المخاوف من اتساع رقعة الاحتجاجات أوروبياً.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660794\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ما الذي أشعل فتيل الاحتجاجات في فرنسا ولماذا تتمدد عدواها إلى أوروبا؟','2026-10-25 19:35:43','متابعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/19/1177456-1958073437.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660794',0),(58,'اندبندنت عربية','2026-10-16 21:00:00','<p>تتراجع حظوظ الجمهوريين مع اقتراب الانتخابات النصفية الأميركية، بعدما تحولت ولايات دائماً ما شكلت معاقل آمنة للحزب، مثل تكساس وكانساس، إلى ساحات تنافس محتدم. وبينما يضطر الجمهوريون إلى إنفاق متزايد للدفاع عن مقاعدهم، تتصاعد فرص الديمقراطيين لاستعادة الغالبية في الكونغرس. وفي خضم هذه التحولات، يزيد ترمب من حدة هجماته على خصومه، فيما بات بعض مرشحي حزبه يأملون في ابتعاده عن حملاتهم الانتخابية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660249\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الجمهوريون أمام احتمال هزيمة قاسية في الانتخابات النصفية','2026-10-25 19:35:43','متابعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/12/1176524-616016676.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660249',0),(59,'اندبندنت عربية','2026-10-13 21:00:00','<p>يكشف استطلاع جديد عن أن غالبية ساحقة من الأميركيين ترفض إنفاق أموال دافعي الضرائب على إعلانات يظهر فيها دونالد ترمب قبيل الانتخابات النصفية. وبينما دافع البيت الأبيض عنها باعتبارها رسائل خدمة عامة، أثارت الحملة موجة انتقادات ودعاوى قضائية دفعت ترمب إلى التعهد بتمويلها من أموال لجنة العمل السياسي التابعة له.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660080\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','دافعو الضرائب يمولون إعلانات ترمب... والأميركيون ممتعضون','2026-10-25 19:35:43','متابعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/10/1176214-1365901069.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660080',0),(60,'اندبندنت عربية','2026-10-13 13:29:16','<p>يسعى بيت هيغسيث إلى استثمار الجدل حول بث إعدام نضال حسن لاستنهاض قاعدة &quot;ماغا&quot; قبيل الانتخابات النصفية، فيما تضع تحركاته وطموحه لخلافة ترمب عام 2028 علاقته بجي دي فانس في إطار تنافس سياسي متصاعد. لكن موقعه داخل الإدارة يبقى هشاً في ظل تعثر الحرب في إيران ومشكلات &quot;البنتاغون&quot;، وقد تنقلب مجازفته عليه إذا جاءت نتائج الجمهوريين سيئة واضطر ترمب إلى البحث عمن يحمله مسؤولية الإخفاق.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660347\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','وصول بيت هيغسيث إلى رئاسة أميركا احتمال مرعب','2026-10-25 19:35:43','تحلیل',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/13/1176700-67875666.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660347',0),(61,'اندبندنت عربية','2026-10-12 13:42:14','<p>يحذر الكاتب من أن بريطانيا باتت أكثر عرضة من أي وقت مضى لهجمات بالطائرات المسيرة والصواريخ، في وقت تعاني دفاعاتها الجوية ثغرات كبيرة مقارنة بحلفائها الأوروبيين. ويرى الخبير أن الخطط المطروحة حالياً أقرب إلى الاستعراض السياسي منها إلى استراتيجية دفاعية حقيقية، محذراً من أن أي هجوم واسع النطاق قد يشل البنية التحتية والاتصالات ويقلب الحياة اليومية رأساً على عقب.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660260\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','\"القباب الحديدية\" الاستعراضية لن تحمي بريطانيا من هجوم وشيك','2026-10-25 19:35:43','تحلیل',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/12/1176544-1430961332.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660260',0),(62,'اندبندنت عربية','2026-10-12 10:18:06','<p>بعد عام على وقف إطلاق النار في غزة، تبدو وعود السلام أبعد من أي وقت مضى. فالهجمات الإسرائيلية لم تتوقف، والأزمة الإنسانية تتفاقم، وإعادة الإعمار تسير ببطء شديد، فيما لا تزال مفاوضات المرحلة الثانية من الهدنة متعثرة، ليبقى السلام بالنسبة إلى سكان القطاع أملاً مؤجلاً أكثر منه واقعاً.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660224\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','عام على \"وقف النار\" في غزة... السلام غائب والهجمات متواصلة','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/12/1176461-951097236.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660224',0),(63,'اندبندنت عربية','2026-10-10 10:32:19','<p>لم ينزل طلاب المدارس الثانوية في فرنسا إلى الشوارع هرباً من الدراسة، بل احتجاجاً على مدارس متداعية، ونقص المعلمين، وضغوط القبول الجامعي. وبين الإرهاق والإحباط، تحولت مطالبهم بتحسين ظروف التعليم إلى حركة احتجاجية واسعة امتدت إلى مختلف أنحاء البلاد.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660079\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','كيف عطلت الاحتجاجات الطلابية الدراسة في فرنسا؟','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/10/1176213-1649088574.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/660079',0),(64,'اندبندنت عربية','2026-10-06 13:12:32','<p>تضع الحرب المتصاعدة في البحر الأسود صادرات الحبوب الأوكرانية والروسية تحت ضغط متزايد، مهددة برفع أسعار الغذاء عالمياً وتعميق معاناة الدول الأكثر اعتماداً على هذه الإمدادات، فيما تبقى طرق التصدير البديلة عاجزة عن تعويض الشحن البحري بالكامل.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659775\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','اشتداد حرب أوكرانيا يهدد بإشعال أسعار الغذاء العالمية','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/06/1175676-1799067238.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659775',0),(65,'اندبندنت عربية','2026-10-06 09:30:34','<p>يكسر عناصر سابقون في القوات الخاصة البريطانية صمتاً امتد عقوداً، كاشفين عن تفاصيل عمليات سرية واشتباكات دامية مع &quot;الجيش الجمهوري الإيرلندي&quot;، ومروين كيف تحولت قرارات اتخذوها خلال لحظات تحت النار إلى تحقيقات وملاحقات قضائية تلاحقهم بعد عقود من انتهاء الصراع.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659746\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','أسرار حرب بريطانيا الدموية ضد \"الجيش الجمهوري الإيرلندي\"','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/06/1175627-1505690001.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659746',0),(66,'اندبندنت عربية','2026-10-05 12:42:08','<p>تحولت مدن شرق أوكرانيا إلى خط دفاع حاسم أمام التقدم الروسي، فيما يخوض سجناء سابقون ورجال شرطة معارك شرسة جنباً إلى جنب للدفاع عن &quot;حزام الحصون&quot; في دونيتسك. وتكشف تجارب مقاتلي &quot;شكفال&quot; و&quot;ليوت&quot; كيف أعادت الحرب رسم العلاقة بين فئات لم يكن متوقعاً أن يجمعها تحالف، وسط قتال متصاعد بالمسيّرات والصواريخ ومعارك المدن.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659675\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','داخل مدن أوكرانيا الحصينة... والسجناء السابقون الذين يحمونها','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/05/1175483-1342222866.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659675',0),(67,'اندبندنت عربية','2026-10-02 08:29:54','<p>تتوسع الحرب الروسية على أوكرانيا إلى بولندا عبر هجمات هجينة تشمل اختراق المجال الجوي، والتخريب، والقرصنة الإلكترونية، والتضليل الإعلامي. وترى وارسو أن موسكو تختبر دفاعات أوروبا وتسعى إلى تقويض دعم كييف، وإثارة التوتر بين البولنديين والأوكرانيين، وإضعاف وحدة الغرب في مواجهة الحرب.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659406\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بوتين يثير الفوضى في بولندا وتداعيات حرب أوكرانيا تمتد إلى أوروبا','2026-10-25 19:35:43','تحلیل',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/02/1175014-2045379626.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659406',0),(68,'اندبندنت عربية','2026-09-29 13:57:53','<p>تتصاعد المخاوف في أوروبا من أن تختبر روسيا تماسك &quot;الناتو&quot; بهجوم عسكري محدود، مستغلة ثغرات في دفاعاته وجاهزيته. وعلى رغم تفوق الحلف عسكرياً واقتصادياً، يحذر خبراء من أن نقص الذخيرة وضعف الدفاعات الجوية وبطء حشد القوات قد تغري موسكو باختبار خطوطه الحمراء.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659212\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بنى أوروبا الحيوية في مرمى روسيا','2026-10-25 19:35:43','تحلیل',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/29/1174640-1576957063.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659212',0),(69,'اندبندنت عربية','2026-09-29 11:43:22','<p>تكشف صور محدثة لـ&quot;غوغل إيرث&quot; حجم الدمار غير المسبوق في غزة، حيث تحولت أحياء بأكملها إلى ركام وتضررت غالبية المنازل والمنشآت الحيوية. وبينما لا تزال جثامين تحت الأنقاض، تتصاعد المخاوف من أن تؤدي عمليات إزالتها إلى طمس أدلة محتملة على جرائم حرب.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659192\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','خرائط محدثة من \"غوغل\" تكشف هول الدمار في غزة','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/29/1174612-210247487.png',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659192',0),(70,'اندبندنت عربية','2026-09-29 08:34:24','<p>على رغم مؤشرات حكومية إلى تحسن الدخل وتراجع انعدام الأمن الغذائي، لا تزال ملايين الأسر البريطانية تكافح لتأمين الطعام وسط ارتفاع حاد في الأسعار. وبين دفع الإيجار والفواتير وشراء الغذاء، يجد بعض الآباء أنفسهم مضطرين إلى الاستغناء عن وجباتهم لإطعام أطفالهم.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659163\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','أزمة الفقر الغذائي تدفع بريطانيين للاكتفاء بوجبة واحدة في اليوم','2026-10-25 19:35:43','تقارير',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/29/1174567-583608144.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659163',0),(71,'اندبندنت عربية','2026-09-28 15:00:35','<p>يتسلل الذكاء الاصطناعي سريعاً إلى ساحات الحرب، من تحديد الأهداف والمراقبة إلى التأثير في قرارات القادة، وسط مخاوف من أن يدفع نحو التصعيد النووي أو يساء استخدامه بيولوجياً. وبين سيناريوهات &quot;نهاية العالم&quot; والمبالغات المحيطة بها، تبدو أخطاره العسكرية والأمنية الراهنة أكثر واقعية وإلحاحاً.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659110\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الذكاء الاصطناعي أداة تغيير المستقبل.. ومن يمسك بمقاليدها ينتصر','2026-10-25 19:35:43','تحلیل',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/28/1174476-327056529.jpg',NULL,'fa fa-balance-scale','اندبندنت عربية','https://www.independentarabia.com/node/659110',0);
