INSERT INTO `post8` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (402787,'اندبندنت عربية','2026-10-24 16:12:27','<p>في وقت تتصاعد الهجمات الروسية ويحصد القصف أرواح الأطفال الأوكرانيين، يثير وصف مبعوث ترمب ستيف ويتكوف للرئيس بوتين بأنه &quot;إنساني&quot; موجة من السخرية والغضب. وتكشف المفارقة عن تناقض الخطاب الأميركي، إذ تتقدم المصالح السياسية على المأساة الإنسانية، فيما يتشكل النظام العالمي وسط تراجع الدور الأميركي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661176\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بوتين \"الإنساني\" يشن الحرب ويسفك دماء أوكرانيين','2026-10-25 19:35:43','آراء',1,0,0,0,1,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/24/1178096-2115029644.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/661176',0),(402788,'اندبندنت عربية','2026-10-22 12:27:41','<p>يحذر جون رينتول من أن الخطر الذي يهدد بريطانيا لا يكمن في الهجرة بحد ذاتها، بل في تصاعد الخطاب المتطرف وتآكل جودة النقاش العام على جانبي الطيف السياسي، ويرى أن الاستقطاب المتزايد وثقافة التخوين المنتشرة عبر وسائل التواصل الاجتماعي قد تهيئان الظروف لاضطرابات وعنف شبيهين بما تشهده فرنسا.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661008\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هل تنزلق بريطانيا إلى فوضى المشهد السياسي الأوروبي؟','2026-10-25 19:35:43','آراء',1,0,0,0,1,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/22/1177827-72447523.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/661008',0),(402789,'اندبندنت عربية','2026-10-22 12:01:41','<p>تمنح أعمال الشغب التي تجتاح فرنسا مارين لوبن فرصة ذهبية لتعزيز حظوظها السياسية، مستفيدة من مشاهد النهب والعنف وانهيار النظام العام. وبينما تتصاعد المخاوف من تحول الفوضى إلى انتصار لليمين المتطرف، يحذر مراقبون من أن المهاجرين وسكان الضواحي الفقيرة سيكونون الخاسر الأكبر.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661006\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مارين لوبن تستعيد زخمها من فوضى فرنسا','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/22/1177819-1286632294.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/661006',0),(402790,'اندبندنت عربية','2026-10-19 12:36:42','<p>على رغم تراجع بنيامين نتنياهو في استطلاعات الرأي، لا تبدو هزيمته مضمونة. فبينما تتعثر المعارضة في تشكيل بديل، لا يزال زعيم حزب الليكود بارعاً في توظف الأزمات لتعزيز صورته حامياً للإسرائيليين، في وقت تتزايد فيه اللامبالاة الشعبية إزاء التحولات المتطرفة التي تهدد الديمقراطية الإسرائيلية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660783\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','أخشى ألا تطيح الانتخابات المقبلة بنتنياهو','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/19/1177434-571025094.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/660783',0),(402791,'اندبندنت عربية','2026-10-15 12:06:45','<p>يدعو شون أوغرايدي إلى إعادة بريطانيا إلى الاتحاد الأوروبي من دون استفتاء جديد، مستلهماً تجربة الانضمام عام 1973. ويرى أن التفويض الشعبي عبر الانتخابات، ثم التفاوض على شروط علاقة أوثق وموافقة البرلمان عليها، يمثلان مساراً ديمقراطياً أكثر حكمة، ويجنبان البلاد انقسامات سياسية أثبتت تجربة &quot;بريكست&quot; خطورتها.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660498\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','عودة بريطانيا للاتحاد الأوروبي لا تحتاج إلى استفتاء جديد','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/15/1176948-1367121441.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/660498',0),(402792,'اندبندنت عربية','2026-10-14 12:56:40','<p>انهارت &quot;هدنة الطاقة&quot; التي أعلنها ترمب سريعاً مع تجدد القصف الروسي على خاركيف، فيما منح تخفيف العقوبات على صادرات الديزل موسكو متنفساً سياسياً واقتصادياً في وقت تتصاعد فيه الضربات المتبادلة على البنية التحتية للطاقة. وتتداخل أزمة الوقود الأميركية والانتخابات النصفية مع الضغوط على كييف لوقف هجماتها داخل روسيا، بينما تتسع الحرب من أوكرانيا إلى الخليج من دون مسار واضح للتسوية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660433\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','شريان حياة أميركي لحرب بوتين في أوكرانيا؟','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/14/1176838-1808624858.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/660433',0),(402793,'اندبندنت عربية','2026-10-09 12:52:53','<p>فيما تتسع احتجاجات الطلاب وأعمال الشغب في فرنسا، يواجه إيمانويل ماكرون انتقادات بسبب غيابه وصمته حيال أزمة تمس جيلاً لم يعرف رئيساً سواه. وترى الكاتبة أن أفضل فرصة أمامه لاستعادة زمام المبادرة تكمن في النزول إلى الميدان، ومحاورة المحتجين مباشرة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660025\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ماكرون.. الغائب عن مشهد الاحتجاجات وأعمال الشغب في فرنسا','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/09/1176120-852618199.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/660025',0),(402794,'اندبندنت عربية','2026-10-09 11:12:46','<p>بعد ثلاثة أعوام على هجمات السابع من أكتوبر، يواجه بنيامين نتنياهو اختباراً انتخابياً حاسماً وسط تصاعد الغضب من الإخفاقات الأمنية ورفض تشكيل لجنة تحقيق مستقلة لمحاسبة المسؤولين عن أكبر كارثة في تاريخ إسرائيل. وبين محاولات الحكومة إعادة صياغة رواية الأحداث، وتراجع ثقة قطاعات من الإسرائيليين، والخلافات في شأن إعفاء الحريديم من الخدمة العسكرية، تتزايد الضغوط على نتنياهو، فيما قد تحدد نتائج انتخابات الـ27 من أكتوبر مصيره السياسي ومستقبل البلاد.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660017\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا يخشى نتنياهو تحقيقا في هجمات 7 أكتوبر؟','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/09/1176100-1065627671.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/660017',0),(402795,'اندبندنت عربية','2026-10-08 14:24:09','<p>بعد ثلاث سنوات على هجمات 7 أكتوبر، تحولت غزة إلى مساحة يعمها الدمار والنزوح والمعاناة، فيما امتد العنف إلى الضفة الغربية. وبينما تتواصل المأساة، يدعو أقارب ضحايا الهجمات إلى التخلي عن منطق الرد والانتقام، ووضع حد للحرب والاحتلال، وإرساء سلام حقيقي قائم على المساءلة وحق تقرير المصير.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659961\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هجمات 7 أكتوبر أدخلت غزة في أتون الحرب','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/08/1176007-1513463790.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659961',0),(402796,'اندبندنت عربية','2026-10-08 12:42:30','<p>وفاة عاملة في مختبر روسي لأبحاث الطاعون تثير مخاوف من احتمال وقوع تسرب بكتيري، وسط غموض يحيط بالحادثة وتساؤلات عن قدرة العالم على مواجهة أخطار صحية جديدة. وفي وقت تقلص إدارة ترمب دعم الأبحاث وتبتعد عن التعاون الصحي الدولي، تتصاعد المخاوف من تراجع الريادة العلمية الأميركية لمصلحة الصين، وإضعاف قدرة واشنطن على التصدي للأوبئة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659950\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','فرضية \"التسرب المختبري\" الروسي... مثيرة للقلق','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/08/1175980-1509907830.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659950',0),(402797,'اندبندنت عربية','2026-10-06 14:17:08','<p>وفاة باحث بالطاعون الرئوي في سيبيريا أعادت المخاوف من أخطار الأوبئة والحوادث المختبرية، لكن الخطر الأكبر قد يكمن في مرض مجهول ينتشر بين البشر. وبينما يظل الطاعون قابلاً للعلاج والسيطرة، تكشف تجارب كوفيد-19 وغيرها عن أن العالم لا يزال يفتقر إلى استراتيجية فعالة لمواجهة الوباء المقبل.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659786\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ما ينبغي أن نخشاه من طاعون سيبيريا','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/06/1175715-93523105.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659786',0),(402798,'اندبندنت عربية','2026-10-04 12:52:05','<p>تتحول احتجاجات طلاب المدارس في فرنسا من مطالب تعليمية مشروعة إلى فوضى وعنف تغذيهما قوى سياسية تسعى إلى استثمار غضب الشباب. وبينما تراهن &quot;فرنسا الأبية&quot; على تعبئة &quot;جيل زد&quot;، تحذر الكاتبة من أن المستفيد الأكبر قد يكون مارين لوبان واليمين المتطرف.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659588\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا يضرم \"جيل زد\" النار في مدارس فرنسا؟','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/04/1175342-125880630.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659588',0),(402799,'اندبندنت عربية','2026-10-04 11:35:37','<p>على رغم سنوات من الحديث عن الطاقة النظيفة لا يزال الاقتصاد البريطاني رهينة الديزل المستورد. ومع ارتفاع الأسعار وتهديد ترمب بوقف الصادرات الأميركية تواجه البلاد أزمة تكشف ثمن تراجع قدراتها على التكرير وضعف احتياطاتها، وتعيد أمن الطاقة إلى صدارة الاهتمام.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659574\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بريطانيا تتجه نحو أزمة طاقة جديدة','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/04/1175314-1144475358.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659574',0),(402800,'اندبندنت عربية','2026-10-02 10:58:00','<p>تواجه أوروبا تهديدات أمنية غير مسبوقة منذ الحرب الباردة، مما يفرض على دول &quot;الناتو&quot; تعزيز قدراتها العسكرية والصناعية والمجتمعية. ويؤكد قائدا الجيشين البريطاني والسويدي أن حماية الجناح الشمالي للحلف لا تعتمد على السلاح وحده، بل على جاهزية المجتمعات والبنية التحتية والكوادر البشرية لردع أي عدوان محتمل.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659423\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الجناح الشمالي لـ\"الناتو\" تحت تهديد غير مسبوق منذ الحرب الباردة','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/02/1175044-103610368.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659423',0),(402801,'اندبندنت عربية','2026-09-30 18:28:35','<p>حقق &quot;التجمع الوطني&quot; مكاسب تاريخية في مجلس الشيوخ الفرنسي، مما عزز حضوره المؤسسي ومنحه زخماً إضافياً قبل الانتخابات الرئاسية المقررة عام 2027. لكن طبيعة انتخابات مجلس الشيوخ غير المباشرة تحد من اعتبار النتائج مؤشراً حاسماً إلى المزاج الشعبي، فيما تتواصل المنافسة بين لوبان وميلونشون ومرشحي الوسط على خلافة ماكرون.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659307\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ماذا تعني مكاسب لوبان لليمين المتطرف قبل الانتخابات الرئاسية الفرنسية؟','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/30/1174835-1506785087.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659307',0),(402802,'اندبندنت عربية','2026-09-30 14:05:17','<p>تكشف حادثة قاعدة &quot;فيرفورد&quot; حجم الثغرات في استعداد بريطانيا لحماية جبهتها الداخلية، وسط تصاعد أخطار التخريب والطائرات المسيرة والهجمات السيبرانية والتهديدات المرتبطة بقوى أجنبية. ويطرح ضعف الجاهزية تساؤلات حول قدرة لندن على الوفاء بالتزاماتها الدفاعية تجاه &quot;الناتو&quot;، والحاجة إلى إصلاح قوات الاحتياط وتعزيز قدرة الدولة على الصمود في مواجهة الأزمات.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659292\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مخطط تفجير قاعدة فيرفورد مؤشر على هشاشة دفاعات بريطانيا','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/30/1174809-1734880803.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659292',0),(402803,'اندبندنت عربية','2026-09-29 12:13:29','<p>يكشف تسارع الذكاء الاصطناعي والعمل الرقمي حاجة متزايدة إلى حماية التواصل الإنساني داخل المؤسسات، إذ لا تستطيع التكنولوجيا وحدها أن تبني التعاطف والقيادة والعلاقات التي تتشكل من التفاعل المباشر بين الناس. وتقدم تجربة &quot;أون هاند&quot; التطوع نموذجاً لاستخدام التكنولوجيا في خدمة الإنسان، عبر وصل المحتاجين إلى الدعم بالراغبين في المساعدة، وفي الوقت نفسه تنمية مهارات الموظفين وتعزيز روابطهم الإنسانية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659198\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الذكاء الاصطناعي يسرع تواصلنا لكنه لا يعوض التواصل الإنساني','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/09/29/1174621-691672811.jpg',NULL,'fa-solid fa-pencil-alt','اندبندنت عربية','https://www.independentarabia.com/node/659198',0);
