INSERT INTO `post9` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405550,'الشرق الأوسط','2026-10-13 10:09:33','<p>تصعب الإصابة به لانتقاله عن طريق سوائل الجسم... إلا أن النزاعات والحروب تزيدها</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5329045\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','العالِم الذي أسهم في اكتشاف «إيبولا» قبل 50 عاماً... لا يزال قلقاً من انتشاره','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1824712.jpeg.webp?VersionId=o1b_82eEOt0uF9vd.bP32KG_zpILa_b_',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5329045',0),(405549,'الشرق الأوسط','2026-10-15 08:33:59','<p>يوسع نطاق ما يمكن للعلماء اكتشافه وقياسه</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5329830\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الذكاء الاصطناعي قد يضاعف ​​عمر الإنسان','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1828329.jpeg.webp?VersionId=YNP7rME9rzgXmq9mQa7aVpESZu151r8R',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5329830',0),(405548,'الشرق الأوسط','2026-10-18 18:13:14','<p>بعد أن تعلّمت فرشاة الأسنان قياس ضغط اليد وحساب وقت التنظيف، بدأت تتعلم كيف «ترى» داخل الفم. فالكاميرا التي تدخل اليوم إلى هذه الأداة اليومية</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5330940\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','فرشاة الأسنان للمراقبة والوقاية المنزلية','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1834442_0.jpeg.webp?VersionId=_2Mv9_NUhuGWpMSVikfWZ.vNEmbDDdzN',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5330940',0),(405547,'الشرق الأوسط','2026-10-20 08:10:28','<p>توقعات بأن تشهد صناعاتها طفرة تكنولوجية على غرار ما حدث في صناعة الذكاء الاصطناعي.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5331455\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الروبوتات الشبيهة بالإنسان... تصاميم مستقلة ومتعددة الأغراض','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1836734.jpeg.webp?VersionId=8o5B9UsPtE8qK6EQugV2hub3py1ebP6M',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5331455',0),(405546,'الشرق الأوسط','2026-10-20 10:41:19','<p>طوَّر الباحثان نِك كولدري وأوليسيس ميخياس مفهوم «استعمار البيانات» لوصف تحويل تفاصيل الحياة البشرية إلى مورد اقتصادي تسيطر عليه جهات أخرى.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5331526\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','«استعمار البيانات الصحية»... من يملك المعرفة والعائد؟','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1836863.jpeg.webp?VersionId=8bP3m1adsyaMPpgy0D2U8BV5ge5Wt5q6',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5331526',0),(405545,'الشرق الأوسط','2026-10-21 07:42:23','<p>الغاية تصبح بمثابة الهيكل المعماري أو المخطط الأساسي لتنظيم حياتك</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5331876\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هل تعاني «قلق الغاية»؟','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1838532.jpeg.webp?VersionId=W3qB9hXDMohMVjnxiqhJ4TtfdXEK0lf5',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5331876',0),(405544,'الشرق الأوسط','2026-10-21 11:15:04','<p>استخدام البرامج بطريقة إبداعية يساعد في بناء خبرة متخصصة</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5331959\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','6 طرق لاستخدام الذكاء الاصطناعي تعزز ذكاءك','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1838770.jpeg.webp?VersionId=nEeVhkic0e2BI_YQ4ZELqUPoAX4EC18d',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5331959',0),(405543,'الشرق الأوسط','2026-10-22 09:06:15','<p>أُخضِعَ لاختبارات تربط بين عناصر ثقافية تبدو غير مترابطة تتطلب إجابات تستند إلى التجربة الحياتية الفعلية</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5332275\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','دراسة كندية: الذكاء الاصطناعي «لا يفهم الثقافات المختلفة حول العالم»','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1840317.jpeg.webp?VersionId=x5j94qxsMOO4gEtdwk_NUyCyaeSOKLan',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5332275',0),(405542,'الشرق الأوسط','2026-10-25 19:44:50','<p>مع تزايد تأثير التغيرات المناخية في الزراعة، أصبحت معرفة ما يُزرع وأين، وحجم المساحات المزروعة، عاملاً مهماً في تقدير إنتاج الغذاء، والاستعداد لنقصه.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5333581\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','تقنية مبتكرة بالذكاء الاصطناعي لتقدير إنتاج الغذاء في أفريقيا','2026-10-25 20:13:48','',1,1,0,0,0,0,0,'https://aawsat.com/s3/files/styles/1008x534/public/2026-10/1847006.jpeg.webp',NULL,'fa-solid fa-robot','الشرق الأوسط','https://aawsat.com/node/5333581',0),(405541,'اندبندنت عربية','2026-10-06 13:45:05','<p>قد يؤدي ميل نماذج الذكاء الاصطناعي إلى مجاملة المستخدم وتأييد موقفه إلى زيادة اقتناعه بأنه على حق، وتقليل استعداده للاعتذار أو إصلاح علاقاته والانفتاح على وجهات نظر مختلفة. وتحذر الدراسة من أن الاعتماد على هذه النماذج في المشكلات الشخصية قد يضعف مهارات التعامل مع الخلافات، فيما تظهر التجارب أنها قد تؤيد أحياناً سلوكاً ضاراً أو حتى غير قانوني.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659782\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','حين يوافقك الذكاء الاصطناعي أكثر مما ينبغي... هنا تكمن المشكلة','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/06/1175704-830914119.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/659782',0),(405540,'اندبندنت عربية','2026-10-06 18:52:57','<p>يحذر البابا لاوون الرابع عشر من خطر يتجاوز سيناريو انقراض البشر، يتمثل في أن يسلب الذكاء الاصطناعي الإنسان استقلاله ومسؤوليته الأخلاقية وروابطه الإنسانية، فيما تتولى الآلات مزيداً من أدوار التفكير والعمل واتخاذ القرار. وتتقاطع مخاوفه مع تحذيرات متصاعدة من داخل قطاع التكنولوجيا نفسه، لكنها تطرح سؤالاً أعمق حول ما إذا كان التقدم التقني سيظل أداة في خدمة الإنسان أم يتحول إلى بديل منه.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659809\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الذكاء الاصطناعي قد لا يفني البشر... لكنه قد يسلبهم إنسانيتهم','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/06/1175745-1958795278.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/659809',0),(405539,'اندبندنت عربية','2026-10-13 17:13:34','<p>تراجعت الثقة بالعلم عالمياً إلى 72 في المئة عام 2025 بعدما بلغت 80 في المئة خلال جائحة كورونا، وكانت أقل بين من يعانون ضغوطاً مالية أو يفتقرون إلى الثقة بأنظمة الرعاية الصحية. وفي أفريقيا جنوب الصحراء، تتداخل أزمات الخدمات الصحية وتراجع المساعدات والمعلومات المضللة والشعور بعدم الاستفادة من البحوث في إضعاف الثقة بالعلم، مما يعقّد تنفيذ البرامج الصحية ومواجهة الأوبئة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660374\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ما الذي بدد ثقة العالم بالعلم بعد جائحة \"كورونا\"؟','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/13/1176743-2131928463.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/660374',0),(405538,'اندبندنت عربية','2026-10-15 11:25:40','<p>بينما تتصاعد المخاوف من احتمال أن يقضي الذكاء الاصطناعي على البشرية، تبقى سيناريوهات الفناء الشامل أقرب إلى التكهنات منها إلى الحقائق العلمية، لكن الخطر الأكثر إلحاحاً قد يكمن في إساءة استخدام هذه التكنولوجيا، أو اختراقها أنظمة حيوية، مما يجعل تنظيمها ضرورة لا تحتمل انتظار كارثة كبرى.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660492\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','\"تشيرنوبل\" الذكاء الاصطناعي... كارثة قد توقظ العالم','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/15/1176941-857045035.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/660492',0),(405537,'اندبندنت عربية','2026-10-15 11:37:50','<p>كشفت دراسة عن أن الاستعمار البريطاني لأستراليا أسهم في تحويل الأحراج المفتوحة إلى غابات كثيفة تراكمت فيها المواد القابلة للاشتعال، مما فاقم أخطار الحرائق. وتبرز النتائج أهمية إحياء ممارسات الحرق التقليدي لدى السكان الأصليين، التي ساعدت على حماية الأراضي والحد من الحرائق الكارثية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660494\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','غابات أستراليا تدفع ثمن الاستعمار والتخلي عن السكان الأصليين','2026-10-25 19:35:43','بيئة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/15/1176943-342733911.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/660494',0),(405536,'اندبندنت عربية','2026-10-16 09:37:22','<p>لم تعد الهجمات الإلكترونية تهدد البيانات والأموال وحدها، بل باتت قادرة على تعطيل سلاسل الإمداد الغذائي وإفراغ رفوف المتاجر وإتلاف المحاصيل والمنتجات. ومع تزايد اعتماد قطاع الغذاء البريطاني على الأنظمة الرقمية، تتصاعد المخاوف من أن يتحول اختراق إلكتروني واسع النطاق إلى أزمة تهدد الأمن الغذائي للبلاد.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660558\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','كيف يمكن لهجوم إلكتروني أن يهدد الأمن الغذائي في بريطانيا؟','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/16/1177058-1810902056.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/660558',0),(405535,'اندبندنت عربية','2026-10-16 14:03:19','<p>تكشف دراسة جديدة عن أن استخدام الذكاء الاصطناعي لـ10 دقائق فقط قد يضعف القدرة على التركيز والمثابرة في المهام المعقدة، وأظهرت تجارب شملت أكثر من 1200 مشارك أن الاعتماد على أدوات مثل &quot;تشات جي بي تي&quot; يحسن الأداء موقتاً، لكنه قد يقلل القدرة على العمل باستقلالية عند توقف المساعدة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660585\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','10 دقائق من استخدام الذكاء الاصطناعي تصعب إنجاز المهام المعقدة','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/16/1177107-123712849.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/660585',0),(405534,'اندبندنت عربية','2026-10-22 12:38:34','<p>تجارب على نماذج ذكاء اصطناعي تكشف استجابات شبيهة بالألم وتدفع باحثين وشركات إلى التساؤل عما إذا كانت الأنظمة المتقدمة تستحق اعتباراً أخلاقياً، على رغم غياب أي دليل على أنها واعية أو تشعر فعلاً. الجدل يتجاوز مصير الآلة إلى البشر أنفسهم، وسط تحذيرات من أن تطبيع القسوة تجاه روبوتات الدردشة قد يؤثر في سلوك مستخدميها ويعزز الحاجة إلى أطر أخلاقية لأبحاث الذكاء الاصطناعي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661011\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لا تعذبوه... هل يشعر الذكاء الاصطناعي بالألم؟','2026-10-25 19:35:43','علوم',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/22/1177834-1555471588.jpg',NULL,'fa-solid fa-robot','اندبندنت عربية','https://www.independentarabia.com/node/661011',0);
