INSERT INTO `post10` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405505,'اندبندنت عربية','2026-10-09 21:00:00','<p>تحذرريبيكا سبارغو من تأثير المحتوى الإباحي العنيف في الأطفال وتصوراتهم عن الجنس والعلاقات، مؤكدة أن مواجهة الخطر لا تقتصر على توعية الأبناء، بل تتطلب أيضاً محاسبة شركات التكنولوجيا وكسر ثقافة الصمت التي تحيط بالعنف الجنسي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659930\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ما يشاهده الأطفال أخطر مما يحسب الأهل','2026-10-25 19:35:43','منوعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/08/1175945-1181887006.jpg',NULL,'fa-solid fa-leaf','اندبندنت عربية','https://www.independentarabia.com/node/659930',0),(405504,'اندبندنت عربية','2026-10-14 18:53:17','<p>بدأ الانتشار الواسع لأدوية إنقاص الوزن يترك أثراً اقتصادياً مباشراً في قطاع الضيافة، إذ تقول منشآت إن زيارات الزبائن تراجعت وإن عاداتهم في الطعام والإنفاق أصبحت أكثر انتقائية. ويأتي هذا التحول فوق ضغوط ارتفاع التكاليف وضعف ثقة المستهلك، مما يدفع القطاع إلى المطالبة بإصلاح الضرائب التجارية وخفض ضريبة القيمة المضافة إلى 10 في المئة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660451\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ما علاقة عقاقير إنقاص الوزن بتراجع أعمال الحانات والمطاعم؟','2026-10-25 19:35:43','منوعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/14/1176872-1337910816.jpg',NULL,'fa-solid fa-leaf','اندبندنت عربية','https://www.independentarabia.com/node/660451',0),(405503,'اندبندنت عربية','2026-10-16 12:58:20','<p>لو عاد شخص من عام 1986 إلى يومنا هذا، لأدهشه أن هاتفاً صغيراً في الجيب صار كاميرا ومصرفاً ومكتبة، وأن الصين أصبحت تصنع ربع السيارات الجديدة المبيعة في بريطانيا. لكن أشياء كثيرة لم تتغير كما قد نتوقع: ما زال الناس يقلقون من روسيا وكلفة السكن، وما زالت القطارات تتأخر والفقر حاضراً، فيما اختفت عادات قديمة وظهرت أخرى لم يكن أحد ليتخيلها.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660578\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الكثير من مسلمات اليوم كان سيبدو استثنائيا قبل 40 عاما','2026-10-25 19:35:43','منوعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/16/1177090-125856039.jpg',NULL,'fa-solid fa-leaf','اندبندنت عربية','https://www.independentarabia.com/node/660578',0),(405502,'اندبندنت عربية','2026-10-24 12:52:44','<p>تفتح السلطات الفيليبينية تحقيقاً في اتهامات لوالد ميغان ماركل بالاحتفاظ بمئات الصور التي توثق اعتداءات جنسية على أطفال، بعدما قال ابنه إنه عثر عليها في أجهزة إلكترونية تركها خلفه. وينفي توماس ماركل الاتهامات، فيما أعربت ميغان عن صدمتها، مؤكدة أن ابتعادها عن والدها كان لحماية أطفالها.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661157\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','والد ميغان ماركل قيد التحقيق بتهم حيازة صور لاستغلال الأطفال','2026-10-25 19:35:43','منوعات',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/24/1178070-793994796.jpg',NULL,'fa-solid fa-leaf','اندبندنت عربية','https://www.independentarabia.com/node/661157',0);
