INSERT INTO `post16` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405553,'الشرق الأوسط','2026-10-13 08:34:01','<p>قيمة «القراءة الثانية» تُقاس بما تضيفه إلى صحة المريض، ومدى قدرتها على اتخاذ قرارات مفيدة</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5329017\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','حين تكشف الصورة مرضاً لم نبحث عنه… الذكاء الاصطناعي يمنح الأشعة «قراءة ثانية»','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1824663.jpeg.webp?VersionId=IuurEU0Dv98CPiSLoikJ_5VdvsYuDfwd',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5329017',0),(405552,'الشرق الأوسط','2026-10-13 11:35:31','<p>تغير الميكروبيوم ربما ساهم في زيادة بعض الاضطرابات الشائعة في العالم الصناعي، من الحساسية إلى الخرف.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5329080\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هل كانت صحة الأمعاء البشرية أفضل في العصور القديمة؟','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1824759.jpeg.webp?VersionId=ok5myOpEUuvkE2xMCLh2NQtP.FNDzGrE',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5329080',0),(405551,'الشرق الأوسط','2026-10-14 08:55:56','<p>أثبتت قدرتها على تحفيز المناعة لدى حيوانات مختبرية</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5329445\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لقاحات تتحدّى الحرارة… هل يحرّرها الذكاء الاصطناعي من الثلاجات؟','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1826543.jpeg.webp?VersionId=a6Tysvf85axB6.WJbubGahnT3W5hKJ8X',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5329445',0),(405550,'الشرق الأوسط','2026-10-18 17:59:15','<p>لطالما لاحظ الأطباء أن الرجال والنساء لا يتعرضون لخطر الإصابة بأمراض القلب بالدرجة نفسها؛ فبعض أمراض القلب الخلقية تكون أكثر شيوعاً أو أشد خطورة لدى الإناث</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5330936\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا لا تتعرض النساء للإصابة بأمراض القلب بالدرجة نفسها كما لدى الرجال؟','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1834434_0.jpeg.webp?VersionId=Ld37XruQXENf9DJwMS4YKws8qXGO3peo',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5330936',0),(405549,'الشرق الأوسط','2026-10-20 09:58:39','<p>أظهرت دراسة حديثة أن متغيرات وراثية في جين «إم سي 1 آر» (MC1R) ترتبط بتسارع تدهور الأعراض الحركية لدى المصابين بمرض باركنسون.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5331510\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','جين شائع يكشف سرّ سرعة تطور مرض باركنسون','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1836779.jpeg.webp?VersionId=Cp9FsbMFTg3NDZABPbGmnhzMPMF7TmqP',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5331510',0),(405548,'الشرق الأوسط','2026-10-20 12:33:11','<p>من وضع برامج بدائية للقضاء على المرض إلى مشاريع علمية لمنع انتشاره</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5331566\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ماذا يجري داخل مختبرات أبحاث الطاعون الروسية؟','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1836972.jpeg.webp?VersionId=.ySlfPVRzgj.CKsLa_05nvOqW7dBnYT3',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5331566',0),(405547,'الشرق الأوسط','2026-10-22 10:55:28','<p>غالبية الدول توظفه لكنها لا تمتلك استراتيجية وطنية مخصصة للذكاء الاصطناعي الصحي</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5332319\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الذكاء الاصطناعي يدخل المستشفيات أسرع من قوانين حماية المرضى','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1840424.jpeg.webp?VersionId=.OQ2nREKdhTDvyfyaHBZrVpWwqqWk4.X',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5332319',0),(405546,'الشرق الأوسط','2026-10-23 13:55:43','<p>بعد أن كان يُنظر إلى تشخيص السرطان في كثير من الحالات بصفته حكماً بالموت، باتت فرص النجاة أفضل لبعض المرضى حتى في أنواع المرض التي كانت تُعدّ شديدة الفتك.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5332764\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','من جراحة البابا إلى اللقاحات الشخصية… ثورة علمية ترسم مستقبل علاج السرطان','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1842236.jpeg.webp?VersionId=yBO8tz_TEq3U.4zXxf.TpTuKSjFo8sti',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5332764',0),(405545,'الشرق الأوسط','2026-10-25 19:41:45','<p>تخيّل مريضاً يدخل عيادة طبيبه مثقلاً بألم مستمر وإرهاق يعطّل حياته اليومية، ويروي معاناته بتفاصيل يعرفها وحده.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5333580\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','حين تصبح الخوارزمية أكثر إقناعاً من المريض','2026-10-25 20:13:48','',1,1,0,0,0,0,0,'https://aawsat.com/s3/files/styles/1008x534/public/2026-10/1847002.jpeg.webp',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5333580',0),(405544,'الشرق الأوسط','2026-10-25 19:49:08','<p>قد يصبح تعزيز مناعة الجسم ضد السرطان ممكناً يوماً ما عبر لقاح يُتناول عن طريق الفم بدلاً من الحقن.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5333582\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','بكتيريا معدّلة وراثياً تفتح باباً جديداً للقاحات السرطان الفموية','2026-10-25 20:13:48','',1,1,0,0,0,0,0,'https://aawsat.com/s3/files/styles/1008x534/public/2026-10/1847009.jpeg.webp',NULL,'fa fa-heartbeat','الشرق الأوسط','https://aawsat.com/node/5333582',0),(405541,'اندبندنت عربية','2026-10-04 11:29:28','<p>يخوض آلاف الأطفال معركة خفية مع &quot;التهاب المفاصل اليفعي&quot;، وسط نقص في الوعي بطبيعة المرض داخل المدارس. وتجسد تجربة جيسيكا وارد، التي عانت الألم والتنمر وسوء الفهم، أهمية إدراك حاجات المصابين وتوفير الدعم الذي يساعدهم في مواصلة تعليمهم وحياتهم بصورة طبيعية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659572\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','آلاف الأطفال يخوضون معركة صامتة مع التهاب المفاصل','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/04/1175309-1136929318.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/659572',0),(405540,'اندبندنت عربية','2026-10-04 12:59:33','<p>لست مضطراً إلى قطع 10 آلاف خطوة يومياً لجني فوائد المشي. تشير الأبحاث إلى أن تسريع الخطى وإضافة فترات قصيرة من المشي عالي الشدة إلى روتينك اليومي قد يعودان بفوائد كبيرة على القلب واللياقة، ويجعلان الحركة اليومية أكثر فاعلية حتى مع عدد أقل من الخطوات.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659592\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','تعديل بسيط في طريقة المشي يحسن صحة القلب','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/04/1175348-1308127131.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/659592',0),(405539,'اندبندنت عربية','2026-10-05 13:00:48','<p>ترتبط الفاكهة الكاملة بمؤشرات أفضل لصحة القلب مقارنة بعصائرها، فيما أبلغ المصابون بعدد من أمراض القلب وعوامل الخطر عن شرب العصير بوتيرة أكبر وتناول الفاكهة بوتيرة أقل. ولا تثبت الدراسة علاقة سببية، لكنها تطرح احتمال أن يكون فقدان الألياف الموجودة في القشور واللب عند العصر أحد العوامل التي تفسر اختلاف التأثير.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659677\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','طريقة تناولك للفاكهة قد تؤثر في خطر إصابتك بأمراض القلب','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/05/1175489-643590849.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/659677',0),(405538,'اندبندنت عربية','2026-10-07 13:09:18','<p>يرتبط ضعف الأداء في اختبارات التفكير والذاكرة وسرعة معالجة المعلومات لدى الأشخاص في الستينيات بارتفاع ملموس في خطر الإصابة بسكتة دماغية مستقبلاً، فيما لم يظهر الارتباط نفسه بالوضوح ذاته لدى الأكبر سناً. وتعزز النتائج أهمية الاهتمام بصحة الدماغ وعوامل الخطر الوعائية في منتصف العمر، مع احتمال أن تسهم الاختبارات الإدراكية مستقبلاً في تحديد الأشخاص الأكثر عرضة للسكتة الدماغية.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/659875\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','نتائج هذه الاختبارات قد تكشف خطر السكتة الدماغية قبل حدوثها','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/07/1175864-1436762243.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/659875',0),(405537,'اندبندنت عربية','2026-10-11 11:40:53','<p>تكشف دراسة حديثة أن المواظبة على النشاط البدني الهوائي لعقود لا تزيد اللياقة فحسب، بل قد تساعد الجسم أيضاً على الحفاظ على قدرته على مقاومة الضغوط والأمراض مع التقدم في العمر. ويشير الباحثون إلى أن هذه &quot;القدرة الحيوية&quot; قد تكون مفتاح فهم الشيخوخة الصحية وإبطاء آثارها.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660164\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','ممارسة بسيطة تسهم في إبطاء الشيخوخة','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/11/1176368-2110665836.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/660164',0),(405535,'اندبندنت عربية','2026-10-13 21:00:00','<p>تسعى تجربة بريطانية واسعة تضم ربع مليون شخص دون سن الـ50 إلى فهم أسباب ارتفاع سرطان الأمعاء، فيما تظهر البيانات أن 96 في المئة من البالغين في بريطانيا لا يحصلون على الكمية اليومية الموصى بها من الألياف، وأن 28 في المئة من الحالات قد تُعزى إلى نقص استهلاكها. ولا تقتصر فوائد الألياف على الهضم، إذ تغذي ميكروبيوم الأمعاء وترتبط بصحة القلب والتمثيل الغذائي والمناعة والصحة النفسية، ويمكن زيادة استهلاكها بتغييرات بسيطة مثل تناول مزيد من الخضراوات والبقول والحبوب الكاملة والمكسرات.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660189\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هل تحمل الألياف مفتاح الوقاية من سرطان الأمعاء؟','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/11/1176407-1176289073.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/660189',0),(405536,'اندبندنت عربية','2026-10-12 12:59:43','<p>تزداد نزلات البرد والإنفلونزا خلال الخريف والشتاء مع نشاط الفيروسات في الطقس البارد، وجفاف الهواء، وقضاء وقت أطول في أماكن مغلقة أقل تهوية، إلى جانب العودة إلى المدارس والعمل والاختلاط بأعداد أكبر من الأشخاص. ويمكن خفض خطر الإصابة عبر النوم الجيد والغذاء المتنوع والهواء النقي والحفاظ على دفء الجسم ونظافة اليدين والأسطح، إضافة إلى تلقي لقاح الإنفلونزا، ولا سيما للفئات الأكثر عرضة للخطر.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660252\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','لماذا نمرض دائما في هذا الوقت من العام؟','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/12/1176538-2054513422.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/660252',0),(405534,'اندبندنت عربية','2026-10-14 12:38:02','<p>ارتبط المشي الأسرع وارتفاع قوة القبضة والساقين بضعف تأثير التقدم في العمر في الوظائف التنفيذية لدى كبار السن الأكثر عرضة للخرف، وبرز تأثير سرعة المشي خصوصاً لدى الرجال. لكن الأرقام المسجلة ليست عتبات طبية معتمدة بعد، وتحتاج النتائج إلى دراسات أطول لمعرفة ما إذا كان الحفاظ على أداء بدني مرتفع يساعد فعلاً في حماية القدرات التنفيذية وتأخير التدهور المعرفي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660432\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','تغيير بسيط في طريقة المشي قد يساعد في الوقاية من الخرف','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/14/1176836-917077115.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/660432',0),(405533,'اندبندنت عربية','2026-10-20 14:33:25','<p>كشفت دراسة جديدة عن أن القمح والتفاح والجزر فقدت ما يصل إلى نصف قيمتها الغذائية خلال العقود الستة الماضية بسبب تدهور التربة والسعي إلى زيادة الإنتاجية الزراعية، ويحذر الباحثون من أن تراجع كثافة المغذيات، مقترناً بانتشار أدوية إنقاص الوزن، قد يفاقم نقص الفيتامينات والمعادن لدى ملايين الأشخاص.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660869\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الخضراوات فقدت نصف قيمتها الغذائية خلال 60 عاما... فما السبب؟','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/20/1177583-835680046.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/660869',0),(405532,'اندبندنت عربية','2026-10-23 11:35:38','<p>تكشف مراجعة شملت بيانات 2.8 مليون مريض بالسكري عن أن اعتلال الشبكية قد يكون مؤشراً مبكراً إلى الخرف، إذ ارتبط بزيادة خطر الإصابة به بنسبة 55 في المئة. ويرى الباحثون أن فحوص العين الدورية قد تساعد في رصد مؤشرات التدهور المعرفي قبل أعوام من ظهور أعراض فقدان الذاكرة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/661082\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مرض في العين قد ينبئ بالخرف قبل أعوام من ظهور الأعراض','2026-10-25 19:35:43','صحة',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/23/1177936-1244363715.jpg',NULL,'fa fa-heartbeat','اندبندنت عربية','https://www.independentarabia.com/node/661082',0);
