INSERT INTO `post19` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405713,'بي بي سي عربي','2026-10-25 20:11:16','<p>أُغلقت صناديق الاقتراع في البرازيل، الأحد، بعد جولة إعادة محتدمة بين الرئيس لولا دا سيلفا ومنافسه اليميني فلافيو بولسونارو. وتبادل المرشحان الاتهامات، إذ حذّر لولا من تهديد سيادة البلاد، فيما اتهم بولسونارو حزب العمال بالفساد.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/c64g144p817wo?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','انتخابات البرازيل: أبرز ما ينبغي معرفته عن جولة الإعادة بين لولا وبولسونارو','2026-10-25 20:13:47','',1,0,0,0,0,0,1,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/70fc/live/b2ed88c0-bd79-11f1-babe-4199b0e7ccea.png',NULL,'fa fa-globe','بي بي سي عربي','https://www.bbc.com/arabic/articles/c64g144p817wo?at_medium=RSS&at_campaign=rss',0),(405627,'بي بي سي عربي','2026-10-25 14:16:41','<p>برشلونة المتصدر وحامل اللقب يريد حسم الكلاسيكو أمام ضيفه وغريمه التقليدي ريال مدريد ضمن المرحلة العاشرة من الدوري الإسباني لكرة القدم، وبالتالي إبعاده عن المنافسة التي يسعى الفريق الملكي للتمسك بها.</p><p class=\"source-note\">المصدر: <a href=\"https://www.bbc.com/arabic/articles/cmg47e3zpypqo?at_medium=RSS&amp;at_campaign=rss\" target=\"_blank\" rel=\"noopener\">بي بي سي عربي</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','الكلاسيكو: برشلونة لتعزيز الصدارة و\"ضربة موجعة\" لريال مدريد','2026-10-25 19:35:52','',1,0,0,0,0,0,0,'https://ichef.bbci.co.uk/ace/ws/800/cpsprodpb/7ecb/live/22c269f0-d07a-11f1-afcb-6b9b9432d8fc.jpg',NULL,'fa fa-globe','بي بي سي عربي','https://www.bbc.com/arabic/articles/cmg47e3zpypqo?at_medium=RSS&at_campaign=rss',0),(405610,'فرانس 24','2026-10-25 18:22:14','<p>يتوجه الصربيون، الأحد، بكثافة غير مسبوقة إلى صناديق الاقتراع في انتخابات تشريعية مبكرة وُصفت بأنها الأشد تنافساً منذ أكثر من 14 عاماً، حيث تتنافس حركة يقودها الطلبة مع حزب الرئيس السابق ألكسندر فوتشيتش. وبلغت نسبة المشاركة بحلول الساعة 16,00 بالتوقيت المحلي (15,00 بتوقيت غرينتش) نحو 56 في المئة، مقابل 42 في المئة في الساعة نفسها من انتخابات 2023، في مؤشر على تحول كبير في المشهد السياسي الصربي.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D8%A7/20261025-%D8%B5%D8%B1%D8%A8%D9%8A%D8%A7-%D8%A5%D9%82%D8%A8%D8%A7%D9%84-%D9%83%D8%AB%D9%8A%D9%81-%D8%B9%D9%84%D9%89-%D8%A7%D9%86%D8%AA%D8%AE%D8%A7%D8%A8%D8%A7%D8%AA-%D8%AA%D8%B4%D8%B1%D9%8A%D8%B9%D9%8A%D8%A9-%D8%AD%D8%A7%D8%B3%D9%85%D8%A9-%D8%AA%D8%B1%D9%8A%D8%AF-%D8%A8%D9%87%D8%A7-%D8%AD%D8%B1%D9%83%D8%A9-%D8%A7%D9%84%D8%B7%D9%84%D8%A8%D8%A9-%D8%A7%D9%84%D8%A5%D8%B7%D8%A7%D8%AD%D8%A9-%D8%A8%D8%AD%D8%B2%D8%A8-%D9%81%D9%88%D8%AA%D8%B4%D9%8A%D8%AA%D8%B4\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','صربيا: إقبال كثيف على انتخابات تشريعية حاسمة تريد بها حركة الطلبة الإطاحة بحزب فوتشيتش','2026-10-25 19:35:50','أوروبا',1,0,0,0,0,0,1,'https://s.france24.com/media/display/8d4dc69a-d03c-11f1-a767-4b25c96ec90e/w:1024/p:16x9/AP26298218958918.jpg',NULL,'fa fa-globe','فرانس 24','https://www.france24.com/ar/%D8%A3%D9%88%D8%B1%D9%88%D8%A8%D8%A7/20261025-%D8%B5%D8%B1%D8%A8%D9%8A%D8%A7-%D8%A5%D9%82%D8%A8%D8%A7%D9%84-%D9%83%D8%AB%D9%8A%D9%81-%D8%B9%D9%84%D9%89-%D8%A7%D9%86%D8%AA%D8%AE%D8%A7%D8%A8%D8%A7%D8%AA-%D8%AA%D8%B4%D8%B1%D9%8A%D8%B9%D9%8A%D8%A9-%D8%AD%D8%A7%D8%B3%D9%85%D8%A9-%D8%AA%D8%B1%D9%8A%D8%AF-%D8%A8%D9%87%D8%A7-%D8%AD%D8%B1%D9%83%D8%A9-%D8%A7%D9%84%D8%B7%D9%84%D8%A8%D8%A9-%D8%A7%D9%84%D8%A5%D8%B7%D8%A7%D8%AD%D8%A9-%D8%A8%D8%AD%D8%B2%D8%A8-%D9%81%D9%88%D8%AA%D8%B',0),(405618,'فرانس 24','2026-10-25 14:16:09','<p>دعت جماعات احتجاج ونقابات في فرنسا، الأحد، إلى تنظيم مظاهرات جديدة وإضراب على مستوى البلاد في الخامس من نوفمبر/تشرين الثاني، سعيا لمواصلة الضغط على الحكومة بعدما ساعدت عملية أمنية ضخمة في احتواء الاضطرابات خلال مسيرات السبت. وأعلنت وزارة الداخلية الفرنسية توقيف 1314 شخصا وإصابة نحو 50 من عناصر الشرطة خلال الاحتجاجات، أي نحو نصف العدد المسجل الأسبوع الماضي، فيما أبدت نقابات الشرطة قلقها من عدم قدرتها على الحفاظ على هذا المستوى من الانتشار الأمني لفترة طويلة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D9%81%D8%B1%D9%86%D8%B3%D8%A7/20261025-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AA%D9%88%D9%82%D9%8A%D9%81-1314-%D8%B4%D8%AE%D8%B5-%D8%A7%D9%84%D9%85%D8%B8%D8%A7%D9%87%D8%B1%D8%A7%D8%AA-%D8%AF%D8%B9%D9%88%D8%A7%D8%AA-%D9%85%D8%B2%D9%8A%D8%AF-%D9%85%D9%86-%D8%A7%D9%84%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-%D8%A5%D8%B6%D8%B1%D8%A7%D8%A8-%D8%B9%D8%A7%D9%85-%D9%86%D9%88%D9%81%D9%85%D8%A8%D8%B1\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','فرنسا: توقيف 1314 شخصا خلال المظاهرات ودعوات لمزيد من الاحتجاجات وإضراب عام في نوفمبر','2026-10-25 19:35:50','فرنسا',1,0,0,0,0,0,0,'https://s.france24.com/media/display/b7dd62bc-d05a-11f1-88d3-5b4a75578ebb/w:1024/p:16x9/AP26297559777844.jpg',NULL,'fa fa-globe','فرانس 24','https://www.france24.com/ar/%D9%81%D8%B1%D9%86%D8%B3%D8%A7/20261025-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D8%AA%D9%88%D9%82%D9%8A%D9%81-1314-%D8%B4%D8%AE%D8%B5-%D8%A7%D9%84%D9%85%D8%B8%D8%A7%D9%87%D8%B1%D8%A7%D8%AA-%D8%AF%D8%B9%D9%88%D8%A7%D8%AA-%D9%85%D8%B2%D9%8A%D8%AF-%D9%85%D9%86-%D8%A7%D9%84%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-%D8%A5%D8%B6%D8%B1%D8%A7%D8%A8-%D8%B9%D8%A7%D9%85-%D9%86%D9%88%D9%81%D9%85%D8%A8%D8%B1',0),(405615,'فرانس 24','2026-10-25 15:22:57','<p>شهدت فرنسا السبت مظاهرات حاشدة شارك فيها مئات الآلاف، اتسمت في معظمها بالسلمية، قبل أن تتحول إلى اشتباكات في باريس ومرسيليا مع حلول المساء. ورغم نشر السلطات 70 ألف عنصر أمني لمنع تكرار اضطرابات الأسبوع الماضي، اندلعت مواجهات في عدد من المدن، وردد متظاهرون هتافات مناهضة للشرطة، بينها &quot;آكاب&quot;، وهو اختصار لعبارة إنكليزية تعني &quot;جميع أفراد الشرطة أوغاد&quot;. وزارة الداخلية الفرنسية أحصت مشاركة 410 آلاف شخص في الاحتجاجات، فيما قدّرت النقابات عدد المشاركين بنحو ضعف هذا الرقم.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D9%81%D9%8A%D8%AF%D9%8A%D9%88/20261025-%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-24-%D8%A3%D9%83%D8%AA%D9%88%D8%A8%D8%B1-%D9%81%D9%8A-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D9%83%D9%8A%D9%81-%D8%AA%D8%B7%D9%88%D8%B1-%D8%A7%D9%84%D9%85%D8%B4%D9%87%D8%AF-%D9%85%D8%B9-%D8%AD%D9%84%D9%88%D9%84-%D8%A7%D9%84%D9%85%D8%B3%D8%A7%D8%A1\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','احتجاجات 24 أكتوبر في فرنسا.. . كيف تطور المشهد مع حلول المساء؟','2026-10-25 19:35:50','',1,0,0,0,0,0,0,'https://s.france24.com/media/display/dc78f7f4-d086-11f1-b6f8-4b25c96ec90e/w:1024/p:16x9/WB272307-O-01-20261025-01.jpg',NULL,'fa fa-globe','فرانس 24','https://www.france24.com/ar/%D9%81%D9%8A%D8%AF%D9%8A%D9%88/20261025-%D8%A7%D8%AD%D8%AA%D8%AC%D8%A7%D8%AC%D8%A7%D8%AA-24-%D8%A3%D9%83%D8%AA%D9%88%D8%A8%D8%B1-%D9%81%D9%8A-%D9%81%D8%B1%D9%86%D8%B3%D8%A7-%D9%83%D9%8A%D9%81-%D8%AA%D8%B7%D9%88%D8%B1-%D8%A7%D9%84%D9%85%D8%B4%D9%87%D8%AF-%D9%85%D8%B9-%D8%AD%D9%84%D9%88%D9%84-%D8%A7%D9%84%D9%85%D8%B3%D8%A7%D8%A1',0),(405611,'فرانس 24','2026-10-25 16:55:38','<p>أدلى ناخبون في البرازيل اليوم الأحد بأصواتهم في جولة إعادة تتسم بالمنافسة الشديدة وقد تدفع ​أكبر دولة في أمريكا اللاتينية بقوة نحو تيار اليمين وتقربها من الولايات المتحدة في إطار تحول أوسع نحو اليمين في أنحاء المنطقة.</p><p class=\"source-note\">المصدر: <a href=\"https://www.france24.com/ar/%D9%81%D9%8A%D8%AF%D9%8A%D9%88/20261025-%D8%A8%D9%88%D9%84%D8%B3%D9%88%D9%86%D8%A7%D8%B1%D9%88-%D8%A3%D9%85-%D9%84%D9%88%D9%84%D8%A7-%D9%85%D9%86-%D8%B3%D9%8A%D9%81%D9%88%D8%B2-%D8%A8%D8%A7%D9%84%D8%A7%D9%86%D8%AA%D8%AE%D8%A7%D8%A8%D8%A7%D8%AA-%D8%A7%D9%84%D8%B1%D8%A6%D8%A7%D8%B3%D9%8A%D8%A9-%D9%81%D9%8A-%D8%A7%D9%84%D8%A8%D8%B1%D8%A7%D8%B2%D9%8A%D9%84\" target=\"_blank\" rel=\"noopener\">فرانس 24</a> — اقرأ الخبر كام