INSERT INTO `post20` (`post_id`, `post_author`, `post_date`, `post_body`, `post_title`, `post_update`, `post_tags`, `published`, `main`, `topmain`, `photographer`, `block`, `post_visits_num`, `inLast`, `post_image`, `extra_images`, `category_icon`, `source_name`, `source_url`, `hidden_legacy`) VALUES (405221,'الشرق الأوسط','2026-10-13 13:09:41','<p>استكشفت المركبة صخوراً غريبة فاتحة اللون على الكوكب الأحمر.</p><p class=\"source-note\">المصدر: <a href=\"https://aawsat.com/node/5329131\" target=\"_blank\" rel=\"noopener\">الشرق الأوسط</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','مركبة «برسيفيرانس» الجوالة تحطم الرقم القياسي للقيادة على سطح المريخ','2026-10-25 20:13:48','',1,0,0,0,0,0,0,'https://static.srpcdigital.com/styles/1008x534/public/2026-10/1824925.jpeg.webp?VersionId=niV9_Xa.h6uKY5FAq.7BP3cRtXgdBRu4',NULL,'fa fa-rocket','الشرق الأوسط','https://aawsat.com/node/5329131',0),(405217,'اندبندنت عربية','2026-10-20 12:35:31','<p>يثير اقتراب قمر اصطناعي روسي من قمر راداري أميركي - فنلندي يدعم الجيش الأوكراني مخاوف من تحول الفضاء إلى ساحة مواجهة عسكرية جديدة. ومع تصاعد التنافس بين الولايات المتحدة وروسيا والصين، يبرز احتمال استخدام أسلحة نووية في المدار كخيار قد يشل شبكات واسعة من الأقمار الاصطناعية، ويهدد القدرات الاستخباراتية والعسكرية، ويقلب معادلات الردع بين القوى الكبرى.</p><p class=\"source-note\">المصدر: <a href=\"https://www.independentarabia.com/node/660853\" target=\"_blank\" rel=\"noopener\">اندبندنت عربية</a> — اقرأ الخبر كاملاً على موقع المصدر.</p>','هل يشعل قمر روسي غامض حربا في الفضاء؟','2026-10-25 19:35:43','آراء',1,0,0,0,0,0,0,'https://www.independentarabia.com/sites/default/files/article/mainimage/2026/10/20/1177547-1274474570.jpg',NULL,'fa fa-rocket','اندبندنت عربية','https://www.independentarabia.com/node/660853',0);
